// 7. BaseAttributeConstraint — discriminator "type" (dateTime/range/regExp),
// default RegexpAttributeConstraint.
func TestOneOfBaseAttributeConstraint(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "dateTime",
			payload:    `{"type":"dateTime"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeConstraint{} },
			wantType:   &DateTimeAttributeConstraint{},
			discSubstr: []string{`"type":"dateTime"`},
		},
		{
			name:       "range",
			payload:    `{"type":"range"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeConstraint{} },
			wantType:   &RangeAttributeConstraint{},
			discSubstr: []string{`"type":"range"`},
		},
		{
			name:       "regExp",
			payload:    `{"type":"regExp"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeConstraint{} },
			wantType:   &RegexpAttributeConstraint{},
			discSubstr: []string{`"type":"regExp"`},
		},
	}
	runDiscriminatorCases(t, "BaseAttributeConstraint", cases)

	// Default: an absent type routes to RegexpAttributeConstraint (the
	// defaultImpl). Every constraint variant requires `type`, so a type-less
	// payload cannot fully decode — confirm it routes to Regexp, not "unknown".
	assertDefaultRoutesTo(t, "BaseAttributeConstraint", &BaseAttributeConstraint{},
		`{}`, "RegexpAttributeConstraint", &RegexpAttributeConstraint{})

	assertUnknownDiscriminator(t, "BaseAttributeConstraint",
		&BaseAttributeConstraint{}, `{"type":"bogus"}`)
}

// 8. ResourceObjectContentData — discriminator "resource".
// authorities/entities/locations/credentials -> ResourceSimpleContentData;
// certificates -> ResourceCertificateContentData;
// secrets -> ResourceSecretContentData.
func TestOneOfResourceObjectContentData(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "authorities",
			payload:    `{"resource":"authorities","uuid":"u","name":"n"}`,
			newWrapper: func() oneOfWrapper { return &ResourceObjectContentData{} },
			wantType:   &ResourceSimpleContentData{},
			discSubstr: []string{`"resource":"authorities"`},
		},
		{
			name:       "entities",
			payload:    `{"resource":"entities","uuid":"u","name":"n"}`,
			newWrapper: func() oneOfWrapper { return &ResourceObjectContentData{} },
			wantType:   &ResourceSimpleContentData{},
			discSubstr: []string{`"resource":"entities"`},
		},
		{
			name:       "locations",
			payload:    `{"resource":"locations","uuid":"u","name":"n"}`,
			newWrapper: func() oneOfWrapper { return &ResourceObjectContentData{} },
			wantType:   &ResourceSimpleContentData{},
			discSubstr: []string{`"resource":"locations"`},
		},
		{
			name:       "credentials",
			payload:    `{"resource":"credentials","uuid":"u","name":"n"}`,
			newWrapper: func() oneOfWrapper { return &ResourceObjectContentData{} },
			wantType:   &ResourceSimpleContentData{},
			discSubstr: []string{`"resource":"credentials"`},
		},
		{
			name:       "certificates",
			payload:    `{"resource":"certificates","uuid":"u","name":"n"}`,
			newWrapper: func() oneOfWrapper { return &ResourceObjectContentData{} },
			wantType:   &ResourceCertificateContentData{},
			discSubstr: []string{`"resource":"certificates"`},
		},
		{
			name:       "secrets",
			payload:    `{"resource":"secrets","uuid":"u","name":"n"}`,
			newWrapper: func() oneOfWrapper { return &ResourceObjectContentData{} },
			wantType:   &ResourceSecretContentData{},
			discSubstr: []string{`"resource":"secrets"`},
		},
	}
	runDiscriminatorCases(t, "ResourceObjectContentData", cases)

	assertUnknownDiscriminator(t, "ResourceObjectContentData",
		&ResourceObjectContentData{}, `{"resource":"bogus","uuid":"u","name":"n"}`)
}

